(function () {
  'use strict';

  var form = document.getElementById('signup-form');
  var successMessage = document.getElementById('success-message');

  var fields = {
    email: document.getElementById('email'),
    password: document.getElementById('password'),
    confirm: document.getElementById('confirm'),
  };

  function errorId(field) {
    return field.id + '-error';
  }

  function showError(field, message) {
    field.setAttribute('aria-invalid', 'true');
    field.setAttribute('aria-describedby', errorId(field));

    var existing = document.getElementById(errorId(field));
    if (existing) {
      existing.textContent = message;
      return;
    }

    var error = document.createElement('p');
    error.id = errorId(field);
    error.className = 'error';
    error.textContent = message;
    field.insertAdjacentElement('afterend', error);
  }

  function clearError(field) {
    field.removeAttribute('aria-invalid');
    field.removeAttribute('aria-describedby');

    var existing = document.getElementById(errorId(field));
    if (existing) {
      existing.remove();
    }
  }

  function validateEmail(value) {
    if (!value.trim()) return 'Email is required.';
    // Simple RFC-5322-inspired check: local@domain.tld
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return 'Enter a valid email address.';
    return null;
  }

  function validatePassword(value) {
    if (!value) return 'Password is required.';
    if (value.length < 8) return 'Password must be at least 8 characters.';
    return null;
  }

  function validateConfirm(confirmValue, passwordValue) {
    if (!confirmValue) return 'Please confirm your password.';
    if (confirmValue !== passwordValue) return 'Passwords do not match.';
    return null;
  }

  function validateField(name) {
    var field = fields[name];
    var message =
      name === 'email' ? validateEmail(field.value)
      : name === 'password' ? validatePassword(field.value)
      : validateConfirm(field.value, fields.password.value);

    if (message) {
      showError(field, message);
      return false;
    }
    clearError(field);
    return true;
  }

  // Errors clear as the user fixes a field on input.
  Object.keys(fields).forEach(function (name) {
    fields[name].addEventListener('input', function () {
      // Only re-validate live once the field has an error showing,
      // so users aren't yelled at while typing for the first time.
      if (fields[name].getAttribute('aria-invalid') === 'true') {
        validateField(name);
      }
      // A changed password invalidates a previously valid confirm too.
      if (
        name === 'password' &&
        fields.confirm.getAttribute('aria-invalid') === 'true'
      ) {
        validateField('confirm');
      }
    });
  });

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var results = Object.keys(fields).map(function (name) {
      return { name: name, valid: validateField(name) };
    });

    var firstInvalid = results.find(function (r) { return !r.valid; });
    if (firstInvalid) {
      fields[firstInvalid.name].focus();
      return;
    }

    // Success: swap the form for a success message without navigation.
    form.hidden = true;
    successMessage.hidden = false;
    successMessage.focus();
  });
})();

