import { test, expect } from '@playwright/test';

const emailError = '#email-error';
const passwordError = '#password-error';
const confirmError = '#confirm-error';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test('submitting empty shows all three errors and focuses email', async ({ page }) => {
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator(emailError)).toHaveText('Email is required.');
  await expect(page.locator(passwordError)).toHaveText('Password is required.');
  await expect(page.locator(confirmError)).toHaveText('Please confirm your password.');

  await expect(page.locator('#email')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#password')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-invalid', 'true');

  // aria-describedby wiring
  await expect(page.locator('#email')).toHaveAttribute('aria-describedby', 'email-error');
  await expect(page.locator('#password')).toHaveAttribute('aria-describedby', 'password-error');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-describedby', 'confirm-error');

  await expect(page.locator('#email')).toBeFocused();
  // No navigation happened
  await expect(page).toHaveURL(/\/$/);
  await expect(page.locator('#signup-form')).toBeVisible();
});

test('typing a valid email clears only that error', async ({ page }) => {
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator(emailError)).toBeVisible();
  await expect(page.locator(passwordError)).toBeVisible();

  await page.locator('#email').fill('user@example.com');
  await page.waitForTimeout(50);

  await expect(page.locator(emailError)).toHaveCount(0);
  await expect(page.locator('#email')).not.toHaveAttribute('aria-invalid');

  // Other errors remain untouched
  await expect(page.locator(passwordError)).toBeVisible();
  await expect(page.locator(confirmError)).toBeVisible();
});

test('password mismatch is caught', async ({ page }) => {
  await page.locator('#email').fill('user@example.com');
  await page.locator('#password').fill('correct-horse-battery');
  await page.locator('#confirm').fill('correct-horse-staple');
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator(confirmError)).toHaveText('Passwords do not match.');
  await expect(page.locator('#confirm')).toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#confirm')).toBeFocused();

  // Fixing the confirm field on input clears the error
  await page.locator('#confirm').fill('correct-horse-battery');
  await expect(page.locator(confirmError)).toHaveCount(0);
});

test('successful submit swaps form for success message without navigation', async ({ page }) => {
  const navigation = page.waitForEvent('framenavigated', { timeout: 1500 }).then(
    () => { throw new Error('Unexpected navigation'); },
    () => {} // timeout means no navigation — good
  );

  await page.locator('#email').fill('user@example.com');
  await page.locator('#password').fill('correct-horse-battery');
  await page.locator('#confirm').fill('correct-horse-battery');
  await page.getByRole('button', { name: 'Sign up' }).click();

  await expect(page.locator('#signup-form')).toBeHidden();
  await expect(page.locator('#success-message')).toBeVisible();
  await expect(page.locator('#success-message')).toContainText('Success!');

  await navigation;
});

